use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::ParseActorIdError;

/// Defines a 128-bit id newtype that prints as 32 hex digits. Ids are
/// generated by shell crates (UUID v7); pure crates only carry them.
macro_rules! hex_id {
    ($(#[$meta:meta])* $name:ident) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        pub struct $name(pub u128);

        crate::hex_serde::hex_serde!($name);

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{:032x}", self.0)
            }
        }

        impl FromStr for $name {
            type Err = ParseActorIdError;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                s.parse::<crate::ActorId>().map(|id| Self(id.0))
            }
        }

        impl $name {
            /// The last 12 hex digits, enough to tell ids apart where
            /// people read them: UUID v7 ids share their leading time digits.
            pub fn short(&self) -> String {
                format!("{:012x}", self.0 & 0xffff_ffff_ffff)
            }
        }
    };
}

hex_id!(
    /// A shared history: a thread together with its forks.
    FamilyId
);
hex_id!(
    /// One line of work (a conversation and the code it changes) within a family.
    ThreadId
);
hex_id!(
    /// A machine running a Silt daemon.
    DeviceId
);

/// BLAKE3 hash of a stored blob.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct BlobHash(pub [u8; 32]);

impl fmt::Display for BlobHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for byte in self.0 {
            write!(f, "{byte:02x}")?;
        }
        Ok(())
    }
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("invalid blob hash {0:?}: expected 64 hex digits")]
pub struct ParseBlobHashError(String);

impl FromStr for BlobHash {
    type Err = ParseBlobHashError;

    fn from_str(text: &str) -> Result<Self, Self::Err> {
        let invalid = || ParseBlobHashError(text.to_owned());
        if text.len() != 64 || !text.is_ascii() {
            return Err(invalid());
        }
        let mut bytes = [0u8; 32];
        for (byte, pair) in bytes.iter_mut().zip(text.as_bytes().chunks(2)) {
            let pair = std::str::from_utf8(pair).map_err(|_| invalid())?;
            *byte = u8::from_str_radix(pair, 16).map_err(|_| invalid())?;
        }
        Ok(Self(bytes))
    }
}

impl fmt::Debug for BlobHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "BlobHash({self})")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_round_trip_as_hex() {
        let thread = ThreadId(0x0001_92ab);
        assert_eq!(thread.to_string().parse::<ThreadId>(), Ok(thread));
        let thread = ThreadId(0x0192_ab00_0000_7000_8000_1234_5678_9abc);
        assert_eq!(thread.short(), thread.to_string()[20..]);
    }
}
